// This CPU harness consumes the real uniquely owned publication only after
// its actual Native/Sources installations. Other scene intents must be empty;
// the general startup scene installer remains the peer's separate contract.
fn acknowledge_native_only(app:&mut App,publication:crate::bevy_renderer::StartupPublication){
 assert!(publication.commands.is_empty());let batch=&publication.batch;assert!(batch.display.is_none()&&batch.interfaces.is_empty()&&batch.motions.is_empty()&&batch.layered.is_empty()&&batch.effects.is_empty()&&batch.menu_requests.is_empty()&&batch.speech_requests.is_empty());assert!(rvn_core::audio_playback::describe(&batch.state,batch.runtime_epoch).unwrap().is_empty());assert!(rvn_core::audio_checkpoint::music_views(&batch.state,batch.runtime_epoch).unwrap().is_empty());let mut startup=app.world_mut().resource_mut::<DebugBootstrap>();assert_eq!(publication.source.instance_id(),startup.owner.snapshot().instance);assert_eq!(startup.owner.video_views().unwrap(),batch.videos);startup.publication_pending=false;
}
fn pcm_from_origin(root:&std::path::Path)->Vec<f32>{let worker=rvn_media::transport::Worker::spawn_proven(root.join("assets/clip.webm"),None).unwrap();let end=Instant::now()+Duration::from_secs(10);let mut pcm=Vec::new();loop{assert!(Instant::now()<end);match worker.poll().unwrap(){Some(rvn_media::transport::Packet::Data(rvn_media::decoder::Chunk::Audio{samples,..}))=>pcm.extend(samples),Some(rvn_media::transport::Packet::Data(rvn_media::decoder::Chunk::End))=>break,Some(rvn_media::transport::Packet::Error(e))=>panic!("{e}"),_=>std::thread::yield_now()}}pcm}
fn advance_native(app:&mut App,audio:&VideoAudio,source:&mut crate::video_audio::Samples,pcm:&[f32],target:u64){let end=Instant::now()+Duration::from_secs(10);let mut nonzero=false;while audio.0.lock().unwrap().delivered_sample_offset().unwrap()<target{assert!(Instant::now()<end);let before=audio.0.lock().unwrap().delivered_sample_offset().unwrap()as usize;let sample=source.next().unwrap();let after=audio.0.lock().unwrap().delivered_sample_offset().unwrap()as usize;if after==before+1{assert_eq!(sample.to_bits(),pcm[before].to_bits());nonzero|=sample!=0.0;}else{assert_eq!(after,before);assert_eq!(sample,0.0);std::thread::sleep(Duration::from_millis(1));}if after%128==0||after==before{let mut players=app.world_mut().remove_resource::<Players>().unwrap();for player in players.players.values_mut(){super::pump(app.world_mut(),player).unwrap();player.position=audio.0.lock().unwrap().position;super::draw(app.world_mut(),player);}app.world_mut().insert_resource(players);}}assert!(nonzero);}
#[test]
fn second_real_startup_publication_retains_actual_decoder_image_pcm_and_cached_right_then_stop_retires_under_gate(){
 let script=SCRIPT.replace("set after=1}","set after=1 video.stop(\"intro\")}");let(root,mut app)=fixture_source(&script);let first=core(&app);let native=native_ready(&mut app,&first);let sources=sources_ready(&mut app,&first);let publication=publish(&mut app,first,native,sources).unwrap();let random=publication.batch.state.random.clone();acknowledge_native_only(&mut app,publication);
 let old=super::restored_sources_for_test(app.world())[0].1.as_ref().unwrap().clone();old.0.lock().unwrap().running=true;let mut source=old.decoder();let pcm=pcm_from_origin(&root);advance_native(&mut app,&old,&mut source,&pcm,10003);let image=app.world().resource::<Players>().players["intro"].image.clone();let entities=app.world().entities().len();let second=core(&app);assert_eq!(second.render_batch().unwrap().state.random,random);let native=prepare_startup(app.world(),&second).unwrap().expect("Unchanged actual source needs no new decoder/readiness job");assert_eq!(super::atomic_restore::retained_counts_for_test(&native),(0,1));assert!(super::pending_source_for_test(app.world()).is_none());let sources=sources_ready(&mut app,&second);let publication=publish(&mut app,second,native,sources).unwrap();let current=super::restored_sources_for_test(app.world())[0].1.as_ref().unwrap().clone();assert!(Arc::ptr_eq(&old.0,&current.0));assert_eq!(app.world().resource::<Players>().players["intro"].image,image);assert_eq!(app.world().entities().len(),entities);assert_eq!(old.0.lock().unwrap().delivered_sample_offset(),Some(10003));assert!(!old.0.lock().unwrap().revoked);assert_eq!(source.next().unwrap().to_bits(),pcm[10003].to_bits());assert_eq!(old.0.lock().unwrap().delivered_sample_offset(),Some(10004));acknowledge_native_only(&mut app,publication);
 // The next actual VideoStop must retire this exact reader, including the
 // right sample cached by consuming its real left just before publication.
 assert_eq!(source.next().unwrap().to_bits(),pcm[10004].to_bits());let before=state(app.world());let stop=app.world().resource::<DebugBootstrap>().owner.prepare_step(rvn_core::editor_debugger::StepKind::Continue).unwrap();assert_ne!(serde_json::to_value(&stop.render_batch().unwrap().state).unwrap(),before);let native=native_ready(&mut app,&stop);let sources=sources_ready(&mut app,&stop);let _publication=publish(&mut app,stop,native,sources).unwrap();assert!(old.0.lock().unwrap().revoked);assert_eq!(old.0.lock().unwrap().delivered_sample_offset(),Some(10005));assert_eq!(source.next(),None);
}
#[test]
fn retained_actual_file_or_image_changed_after_ready_refuses_second_publication_without_revoking_source(){
 for corrupt_file in [false,true]{let(root,mut app)=fixture_source(SCRIPT);let first=core(&app);let native=native_ready(&mut app,&first);let sources=sources_ready(&mut app,&first);let publication=publish(&mut app,first,native,sources).unwrap();acknowledge_native_only(&mut app,publication);let old=super::restored_sources_for_test(app.world())[0].1.as_ref().unwrap().clone();old.0.lock().unwrap().running=true;let mut source=old.decoder();source.next().unwrap();let second=core(&app);let native=prepare_startup(app.world(),&second).unwrap().unwrap();assert_eq!(super::atomic_restore::retained_counts_for_test(&native),(0,1));let sources=sources_ready(&mut app,&second);
 if corrupt_file{let mut bytes=CLIP.to_vec();let last=bytes.len()-1;bytes[last]^=1;std::fs::write(root.join("assets/mask.webm"),bytes).unwrap();}else{let image=app.world().resource::<Players>().players["intro"].image.clone();app.world_mut().resource_mut::<Assets<Image>>().remove(image.id());}
 let before=state(app.world());let entities=app.world().entities().len();assert!(publish(&mut app,second,native,sources).is_err());assert_eq!(state(app.world()),before);assert_eq!(app.world().entities().len(),entities);assert!(!old.0.lock().unwrap().revoked);assert_eq!(old.0.lock().unwrap().delivered_sample_offset(),Some(1));assert!(source.next().is_some());assert!(!app.world().resource::<DebugBootstrap>().publication_pending);
 }
}

#[test]
fn same_position_real_init_seek_retires_reader_even_though_logical_track_is_equal(){
 let script=SCRIPT.replace("set after=1}","video.seek(\"intro\",0.0) set after=1}");let(root,mut app)=fixture_source(&script);let first=core(&app);let native=native_ready(&mut app,&first);let sources=sources_ready(&mut app,&first);let publication=publish(&mut app,first,native,sources).unwrap();acknowledge_native_only(&mut app,publication);
 let old=super::restored_sources_for_test(app.world())[0].1.as_ref().unwrap().clone();old.0.lock().unwrap().running=true;let mut source=old.decoder();let pcm=pcm_from_origin(&root);advance_native(&mut app,&old,&mut source,&pcm,10003);let image=app.world().resource::<Players>().players["intro"].image.clone();let second=core(&app);let live=app.world().resource::<DebugBootstrap>().owner.video_views().unwrap();assert_eq!(second.render_batch().unwrap().videos[0].track,live[0].track,"Real Seek0 leaves the logical track equal; capability and true command trace still revoke it");let native=native_ready(&mut app,&second);assert_eq!(super::atomic_restore::retained_counts_for_test(&native),(1,0),"Real Seek must not be mistaken for unchanged reader via f64 or absent token");let sources=sources_ready(&mut app,&second);let _publication=publish(&mut app,second,native,sources).unwrap();let current=super::restored_sources_for_test(app.world())[0].1.as_ref().unwrap().clone();assert!(!Arc::ptr_eq(&old.0,&current.0));assert!(old.0.lock().unwrap().revoked);assert_eq!(source.next(),None);assert_eq!(current.0.lock().unwrap().delivered_sample_offset(),Some(0));assert_ne!(app.world().resource::<Players>().players["intro"].image,image);
}
#[test]
fn actual_pause_resume_retains_pcm_cursor_and_right_without_output_before_fence_or_silence_after_resume(){
 let script=SCRIPT.replace("set after=1}","video.pause(\"intro\") video.resume(\"intro\") set after=1}");let(root,mut app)=fixture_source(&script);let first=core(&app);let native=native_ready(&mut app,&first);let sources=sources_ready(&mut app,&first);let publication=publish(&mut app,first,native,sources).unwrap();acknowledge_native_only(&mut app,publication);
 let old=super::restored_sources_for_test(app.world())[0].1.as_ref().unwrap().clone();old.0.lock().unwrap().running=true;let mut source=old.decoder();let pcm=pcm_from_origin(&root);advance_native(&mut app,&old,&mut source,&pcm,10003);let image=app.world().resource::<Players>().players["intro"].image.clone();
 let pause=core(&app);assert_eq!(pause.render_batch().unwrap().videos[0].track.playback,Playback::Paused);let native=prepare_startup(app.world(),&pause).unwrap().unwrap();assert_eq!(super::atomic_restore::retained_counts_for_test(&native),(0,1));let sources=sources_ready(&mut app,&pause);assert!(old.0.lock().unwrap().running,"Preparation must not pause the outgoing reader");let publication=publish(&mut app,pause,native,sources).unwrap();assert!(!old.0.lock().unwrap().running);let offset=old.0.lock().unwrap().delivered_sample_offset();for _ in 0..4{assert_eq!(source.next(),Some(0.0));}assert_eq!(old.0.lock().unwrap().delivered_sample_offset(),offset);acknowledge_native_only(&mut app,publication);
 let resume=core(&app);assert_eq!(resume.render_batch().unwrap().videos[0].track.playback,Playback::Playing);let native=prepare_startup(app.world(),&resume).unwrap().unwrap();assert_eq!(super::atomic_restore::retained_counts_for_test(&native),(0,1));let sources=sources_ready(&mut app,&resume);assert!(!old.0.lock().unwrap().running,"Preparation must not resume before the true fence");assert_eq!(source.next(),Some(0.0));assert_eq!(old.0.lock().unwrap().delivered_sample_offset(),Some(10003));let _publication=publish(&mut app,resume,native,sources).unwrap();assert!(old.0.lock().unwrap().running,"Resume must admit the retained reader under the true fence before any later tick");let current=super::restored_sources_for_test(app.world())[0].1.as_ref().unwrap().clone();assert!(Arc::ptr_eq(&old.0,&current.0));assert_eq!(app.world().resource::<Players>().players["intro"].image,image);for _ in 0..2{let before=old.0.lock().unwrap().delivered_sample_offset().unwrap();let value=source.next().unwrap();if old.0.lock().unwrap().delivered_sample_offset()==Some(before+1){assert_eq!(value.to_bits(),pcm[10003].to_bits());break;}}assert_eq!(old.0.lock().unwrap().delivered_sample_offset(),Some(10004));
}

#[test]
fn actual_second_play_changed_mask_stages_new_definition_and_retires_old_reader_before_install(){
 let script=SCRIPT.replace("set after=1}","video.play(\"intro\",video_clip(\"clip.webm\",{\"mask\":\"mask2.webm\",\"volume\":0.3})) set after=1}");let(root,mut app)=fixture_source(&script);std::fs::write(root.join("assets/mask2.webm"),CLIP).unwrap();let first=core(&app);let native=native_ready(&mut app,&first);let sources=sources_ready(&mut app,&first);let publication=publish(&mut app,first,native,sources).unwrap();let random=publication.batch.state.random.clone();acknowledge_native_only(&mut app,publication);
 let old=super::restored_sources_for_test(app.world())[0].1.as_ref().unwrap().clone();old.0.lock().unwrap().running=true;let mut source=old.decoder();let pcm=pcm_from_origin(&root);advance_native(&mut app,&old,&mut source,&pcm,10003);let image=app.world().resource::<Players>().players["intro"].image.clone();let second=core(&app);assert_eq!(second.render_batch().unwrap().state.random,random);assert_eq!(second.render_batch().unwrap().videos[0].track.clip.mask.as_deref(),Some("mask2.webm"));let native=native_ready(&mut app,&second);assert_eq!(super::atomic_restore::retained_counts_for_test(&native),(1,0));assert!(!old.0.lock().unwrap().revoked);let sources=sources_ready(&mut app,&second);let publication=publish(&mut app,second,native,sources).unwrap();assert_eq!(publication.batch.videos[0].track.clip.mask.as_deref(),Some("mask2.webm"));let current=super::restored_sources_for_test(app.world())[0].1.as_ref().unwrap().clone();assert!(!Arc::ptr_eq(&old.0,&current.0));assert!(old.0.lock().unwrap().revoked);assert_eq!(source.next(),None);assert_eq!(current.0.lock().unwrap().delivered_sample_offset(),Some(0));assert_ne!(app.world().resource::<Players>().players["intro"].image,image);let pixels=super::current_pixels_for_test(app.world());assert!(pixels.chunks_exact(4).any(|p|p[3]<255));
}
#[test]
fn actual_target_change_to_absent_interface_is_refused_before_old_native_reader_changes(){
 let script=SCRIPT.replace("set after=1}","video.play(\"intro\",video_clip(\"clip.webm\",{\"target\":\"ui:missing/player\"})) set after=1}");let(root,mut app)=fixture_source(&script);let first=core(&app);let native=native_ready(&mut app,&first);let sources=sources_ready(&mut app,&first);let publication=publish(&mut app,first,native,sources).unwrap();acknowledge_native_only(&mut app,publication);let old=super::restored_sources_for_test(app.world())[0].1.as_ref().unwrap().clone();old.0.lock().unwrap().running=true;let mut source=old.decoder();let pcm=pcm_from_origin(&root);advance_native(&mut app,&old,&mut source,&pcm,10003);let before=state(app.world());let entities=app.world().entities().len();let image=app.world().resource::<Players>().players["intro"].image.clone();let error=app.world().resource::<DebugBootstrap>().owner.prepare_step(rvn_core::editor_debugger::StepKind::Continue).err().expect("Actual Core must reject absent target before Native sees a desired DTO");assert!(error.to_string().contains("target"),"{error}");assert_eq!(state(app.world()),before);assert_eq!(app.world().entities().len(),entities);assert_eq!(app.world().resource::<Players>().players["intro"].image,image);assert_eq!(old.0.lock().unwrap().delivered_sample_offset(),Some(10003));assert!(!old.0.lock().unwrap().revoked);assert_eq!(source.next().unwrap().to_bits(),pcm[10003].to_bits());
}

#[test]
fn real_legacy_label_init_seek_at_same_position_also_requires_new_actual_decoder(){
 let script=SCRIPT.replace("scene label start","label start").replace("set after=1}","video.seek(\"intro\",0.0) set after=1}");let(root,mut app)=fixture_source(&script);let first=core(&app);let native=native_ready(&mut app,&first);let sources=sources_ready(&mut app,&first);let publication=publish(&mut app,first,native,sources).unwrap();acknowledge_native_only(&mut app,publication);let old=super::restored_sources_for_test(app.world())[0].1.as_ref().unwrap().clone();old.0.lock().unwrap().running=true;let mut source=old.decoder();let pcm=pcm_from_origin(&root);advance_native(&mut app,&old,&mut source,&pcm,10003);let second=core(&app);let actual=app.world().resource::<DebugBootstrap>().owner.video_views().unwrap();assert_eq!(actual[0].track,second.render_batch().unwrap().videos[0].track);let native=native_ready(&mut app,&second);assert_eq!(super::atomic_restore::retained_counts_for_test(&native),(1,0));let sources=sources_ready(&mut app,&second);let _publication=publish(&mut app,second,native,sources).unwrap();let current=super::restored_sources_for_test(app.world())[0].1.as_ref().unwrap().clone();assert!(!Arc::ptr_eq(&old.0,&current.0));assert!(old.0.lock().unwrap().revoked);assert_eq!(source.next(),None);assert_eq!(current.0.lock().unwrap().delivered_sample_offset(),Some(0));
}

#[test]
fn actual_volume_command_rebinds_capability_and_gain_without_resetting_actual_pcm(){
 let script=SCRIPT.replace("set after=1}","video.volume(\"intro\",0.25) set after=1}");let(root,mut app)=fixture_source(&script);let first=core(&app);let native=native_ready(&mut app,&first);let sources=sources_ready(&mut app,&first);let publication=publish(&mut app,first,native,sources).unwrap();let random=publication.batch.state.random.clone();acknowledge_native_only(&mut app,publication);let old=super::restored_sources_for_test(app.world())[0].1.as_ref().unwrap().clone();old.0.lock().unwrap().running=true;let mut source=old.decoder();let pcm=pcm_from_origin(&root);advance_native(&mut app,&old,&mut source,&pcm,10003);let image=app.world().resource::<Players>().players["intro"].image.clone();let entity=app.world().resource::<Players>().players["intro"].audio_entity.unwrap();let second=core(&app);assert_eq!(second.render_batch().unwrap().state.random,random);assert_eq!(second.render_batch().unwrap().videos[0].track.clip.volume,0.25);let native=prepare_startup(app.world(),&second).unwrap().unwrap();assert_eq!(super::atomic_restore::retained_counts_for_test(&native),(0,1));let sources=sources_ready(&mut app,&second);let publication=publish(&mut app,second,native,sources).unwrap();let row=&app.world().resource::<Players>().players["intro"];assert_eq!(row.image,image);assert_eq!(row.audio_entity,Some(entity));assert!(Arc::ptr_eq(&old.0,&row.audio.as_ref().unwrap().0));assert!(old.0.lock().unwrap().verifies_view(publication.source.instance_id(),&publication.batch.videos[0]));assert_eq!(old.0.lock().unwrap().delivered_sample_offset(),Some(10003));assert_eq!(app.world().get::<bevy::audio::PlaybackSettings>(entity).unwrap().volume.get(),0.25);assert_eq!(source.next().unwrap().to_bits(),pcm[10003].to_bits());
}
